#include "oneblock_vectors.hpp"
#include "streaming_master.hpp"
#include "stage2_opening.hpp"
namespace zkgpt::r7::oneblock {
namespace {
void shape(const VectorPC&p){need(!p.id.empty() && p.id.size()<=160 && p.actual>0 && p.actual<=p.padded && p.padded<=(1u<<24) && !(p.padded&(p.padded-1)) && p.columns==std::min<std::size_t>(p.padded,1024) && p.rows==p.padded/p.columns && p.points.size()==p.rows,"Oneblock vector shape");}
}
Bytes encodeVector(const VectorPC&p){shape(p);Writer w;w.text("R7-ONEBLOCK-HIDING-VECTOR-PC-v1");w.text(p.id);for(auto n:{p.actual,p.padded,p.rows,p.columns})w.number(n,8);for(auto&x:p.points)w.point(x);return w.b;}
VectorPC decodeVector(const Bytes&b){Reader r{b};need(r.text()=="R7-ONEBLOCK-HIDING-VECTOR-PC-v1","Oneblock unknown vector PC suite");VectorPC p;p.id=r.text();p.actual=r.number(8);p.padded=r.number(8);p.rows=r.number(8);p.columns=r.number(8);need(p.rows>0 && p.rows<=16384,"Oneblock vector row bound");for(std::size_t i=0;i<p.rows;++i)p.points.push_back(r.point());r.end();shape(p);return p;}
VectorSecret commitVectorOwned(std::string id,std::size_t actual,std::size_t padded,std::shared_ptr<std::vector<Fr>>values,Random&rng){VectorSecret s;s.pc.id=std::move(id);s.pc.actual=actual;s.pc.padded=padded;s.pc.columns=std::min<std::size_t>(padded,1024);need(s.pc.columns>0,"Oneblock vector empty");s.pc.rows=padded/s.pc.columns;s.pc.points.resize(s.pc.rows);shape(s.pc);need(values && values->size()==padded,"Oneblock owned buffer shape");s.values=std::move(values);auto g=hyrax_a3::generators(s.pc.columns);std::vector<Fr>row(s.pc.columns);for(std::size_t i=0;i<s.pc.rows;++i){for(std::size_t j=0;j<s.pc.columns;++j)row[j]=s.values->at(i+s.pc.rows*j);auto rho=rng.scalar();s.blinds.push_back(rho);s.pc.points[i]=master3::masterMSM(g,row)+parameters(1).hiding*rho;}return s;}
VectorSecret commitVector(std::string id,std::size_t actual,std::size_t padded,Value read,Random&rng){need(bool(read),"Oneblock private vector missing");need(padded>0 && padded<=(1u<<24),"Oneblock vector allocation bound");auto values=std::make_shared<std::vector<Fr>>(padded);for(std::size_t i=0;i<padded;++i)values->at(i)=read(i);return commitVectorOwned(std::move(id),actual,padded,std::move(values),rng);}
void openVector(IO&io,const VectorPC&p,const Query&q,const VectorSecret*s,const Hidden*h,Random*rng,const std::string&role){shape(p);need(q.point.size()==r1::log2exact(p.padded),"Oneblock vector query shape");Writer b;b.text("R7-ONEBLOCK-HIDING-VECTOR-OPEN-v1");b.raw(encodeVector(p));b.raw(encode(q.evaluation));for(auto&x:q.point)b.scalar(x);bindPublic(io,role+"/binding",b.b);auto d=r1::log2exact(p.rows);auto L=r1::weights({q.point.begin(),q.point.begin()+d}),a=r1::weights({q.point.begin()+d,q.point.end()});auto xi=master3::masterMSM(p.points,L);hyrax_a3::DotWitness w;if(io.prover()){need(s && h && s->values && encodeVector(s->pc)==encodeVector(p),"Oneblock vector secret identity");w.values.assign(p.columns,Fr(0));w.evaluation=*h;for(std::size_t i=0;i<p.rows;++i){w.blind+=L[i]*s->blinds[i];for(std::size_t j=0;j<p.columns;++j)w.values[j]+=L[i]*s->values->at(i+p.rows*j);}}stage2::ScopedIO scoped(io,role);hyrax_a3::dotProduct(scoped,xi,q.evaluation,a,io.prover()?&w:nullptr,rng);}
VectorOracle exchangeVector(IO&io,std::string id,std::size_t actual,std::size_t padded,Value read,Random*rng,std::function<void(const VectorPC&)>bound){auto secret=std::make_shared<VectorSecret>();Bytes b;if(io.prover()){need(rng,"Oneblock vector entropy required");*secret=commitVector(id,actual,padded,std::move(read),*rng);b=encodeVector(secret->pc);}b=io.message("Oneblock/object/"+id+"/PC",b);auto pc=decodeVector(b);need(pc.id==id && pc.actual==actual && pc.padded==padded,"Oneblock wrong object identity");if(bound)bound(pc);VectorOracle out;out.id=id;out.actual=actual;out.padded=padded;if(io.prover())out.value=[secret](std::size_t i){return secret->values->at(i);};out.open=[secret,pc](IO&live,const Query&q,const Hidden*h,Random*r,std::string role){openVector(live,pc,q,live.prover()?secret.get():nullptr,h,r,role);};return out;}
}
